-- Chronic Care Loop · relational backend (PostgreSQL)
-- Generated by tools/gen_schema.js from src/hub/database.html. Sample rows are synthetic.

-- People who build cohorts, review members and make calls.
CREATE TABLE care_team_user (
  user_id          TEXT NOT NULL,
  name             TEXT NOT NULL,
  role             TEXT NOT NULL,
  languages        TEXT NOT NULL,
  PRIMARY KEY (user_id)
);

-- One row per person, loaded from Daman / SEHA / PURA.
CREATE TABLE member (
  member_id        TEXT NOT NULL,
  mask             TEXT NOT NULL,
  full_name        TEXT NOT NULL,
  age              INT NOT NULL,
  sex              CHAR(1) NOT NULL,
  plan             TEXT NOT NULL,
  language         TEXT NOT NULL,
  base             TEXT NOT NULL,
  segment          CHAR(1) NOT NULL,
  consent_status   TEXT NOT NULL,
  PRIMARY KEY (member_id)
);

-- Reusable measures: the catalogue, plus features created from the knowledge graph.
CREATE TABLE feature (
  feature_key      TEXT NOT NULL,
  label            TEXT NOT NULL,
  source           TEXT NOT NULL,
  category         TEXT NOT NULL,
  value_type       TEXT NOT NULL,
  unit             TEXT,
  definition       TEXT,
  created_by       TEXT NOT NULL,
  created_at       TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (feature_key),
  FOREIGN KEY (created_by) REFERENCES care_team_user (user_id)
);

-- Each member's value for each feature, refreshed every night.
CREATE TABLE member_feature (
  member_id        TEXT NOT NULL,
  feature_key      TEXT NOT NULL,
  value            TEXT NOT NULL,
  as_of            TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (member_id, feature_key),
  FOREIGN KEY (member_id) REFERENCES member (member_id),
  FOREIGN KEY (feature_key) REFERENCES feature (feature_key)
);

-- A named definition of who is in. Saving an edit bumps the version; campaigns always use the current one.
CREATE TABLE cohort (
  cohort_id        TEXT NOT NULL,
  version          INT NOT NULL,
  name             TEXT NOT NULL,
  base             TEXT NOT NULL,
  logic            TEXT NOT NULL,
  refresh          TEXT NOT NULL,
  row_count        INT NOT NULL,
  owner            TEXT NOT NULL,
  created_at       TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (cohort_id),
  FOREIGN KEY (owner) REFERENCES care_team_user (user_id)
);

-- The rules of each cohort version, each on one feature. Old versions are kept for audit.
CREATE TABLE cohort_rule (
  rule_id          TEXT NOT NULL,
  cohort_id        TEXT NOT NULL,
  version          INT NOT NULL,
  feature_key      TEXT NOT NULL,
  operator         TEXT NOT NULL,
  value            TEXT NOT NULL,
  value2           TEXT,
  is_exclusion     BOOL NOT NULL,
  PRIMARY KEY (rule_id),
  FOREIGN KEY (cohort_id) REFERENCES cohort (cohort_id),
  FOREIGN KEY (feature_key) REFERENCES feature (feature_key)
);

-- Who matched a cohort version on its last run. 10% are held out as the control group.
CREATE TABLE cohort_member (
  cohort_id        TEXT NOT NULL,
  version          INT NOT NULL,
  member_id        TEXT NOT NULL,
  holdout          BOOL NOT NULL,
  run_at           TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (cohort_id, member_id),
  FOREIGN KEY (cohort_id) REFERENCES cohort (cohort_id),
  FOREIGN KEY (member_id) REFERENCES member (member_id)
);

-- Puts cohorts to work: which triggers, which channels, how much nurse time, when.
CREATE TABLE campaign (
  campaign_id      TEXT NOT NULL,
  name             TEXT NOT NULL,
  goal             TEXT NOT NULL,
  trigger_mode     TEXT NOT NULL,
  channels         TEXT[] NOT NULL,
  nurses           INT NOT NULL,
  calls_per_day    INT NOT NULL,
  holdout_pct      INT NOT NULL,
  start_date       DATE NOT NULL,
  weeks            INT NOT NULL,
  priority         INT NOT NULL,
  status           TEXT NOT NULL,
  PRIMARY KEY (campaign_id)
);

-- Which cohorts a campaign includes or leaves out.
CREATE TABLE campaign_cohort (
  campaign_id      TEXT NOT NULL,
  cohort_id        TEXT NOT NULL,
  role             TEXT NOT NULL,
  PRIMARY KEY (campaign_id, cohort_id),
  FOREIGN KEY (campaign_id) REFERENCES campaign (campaign_id),
  FOREIGN KEY (cohort_id) REFERENCES cohort (cohort_id)
);

-- A trigger raised for a member in a campaign, with its evidence.
CREATE TABLE signal (
  signal_id        TEXT NOT NULL,
  member_id        TEXT NOT NULL,
  campaign_id      TEXT NOT NULL,
  code             TEXT NOT NULL,
  class            TEXT NOT NULL,
  severity         TEXT NOT NULL,
  evidence         TEXT NOT NULL,
  run_at           TIMESTAMPTZ NOT NULL,
  status           TEXT NOT NULL,
  PRIMARY KEY (signal_id),
  FOREIGN KEY (member_id) REFERENCES member (member_id),
  FOREIGN KEY (campaign_id) REFERENCES campaign (campaign_id)
);

-- Nightly risk score (0–23) and tier, with its five parts.
CREATE TABLE risk_score (
  member_id        TEXT NOT NULL,
  run_at           TIMESTAMPTZ NOT NULL,
  r_total          INT NOT NULL,
  tier             INT NOT NULL,
  clinical         INT NOT NULL,
  comorbid         INT NOT NULL,
  kidney           INT NOT NULL,
  utilisation      INT NOT NULL,
  age_sex          INT NOT NULL,
  alert            TEXT NOT NULL,
  PRIMARY KEY (member_id, run_at),
  FOREIGN KEY (member_id) REFERENCES member (member_id)
);

-- One active plan per consented member: pathway, tier and contact cadence.
CREATE TABLE care_plan (
  care_plan_id     TEXT NOT NULL,
  member_id        TEXT NOT NULL,
  pathway          TEXT NOT NULL,
  tier             INT NOT NULL,
  cadence          TEXT NOT NULL,
  status           TEXT NOT NULL,
  opened_at        TIMESTAMPTZ NOT NULL,
  PRIMARY KEY (care_plan_id),
  FOREIGN KEY (member_id) REFERENCES member (member_id)
);

-- The plan's needs in safety order. The top three are CURRENT and each has one action.
CREATE TABLE care_plan_need (
  need_id          TEXT NOT NULL,
  care_plan_id     TEXT NOT NULL,
  signal_id        TEXT,
  need_key         TEXT NOT NULL,
  class            TEXT NOT NULL,
  slot             TEXT NOT NULL,
  title            TEXT NOT NULL,
  owner_role       TEXT NOT NULL,
  done_when        TEXT NOT NULL,
  due_date         DATE NOT NULL,
  status           TEXT NOT NULL,
  PRIMARY KEY (need_id),
  FOREIGN KEY (care_plan_id) REFERENCES care_plan (care_plan_id),
  FOREIGN KEY (signal_id) REFERENCES signal (signal_id)
);

-- Everything on someone's to-do list: calls, care-plan actions, callbacks, retries, check-ins.
CREATE TABLE action (
  action_id        TEXT NOT NULL,
  member_id        TEXT NOT NULL,
  need_id          TEXT,
  kind             TEXT NOT NULL,
  title            TEXT NOT NULL,
  agreed           BOOL NOT NULL,
  due_date         DATE NOT NULL,
  assignee         TEXT NOT NULL,
  status           TEXT NOT NULL,
  closed_at        TIMESTAMPTZ,
  PRIMARY KEY (action_id),
  FOREIGN KEY (member_id) REFERENCES member (member_id),
  FOREIGN KEY (need_id) REFERENCES care_plan_need (need_id),
  FOREIGN KEY (assignee) REFERENCES care_team_user (user_id)
);

-- One call attempt: who, when, whether reached, consent and the member's response.
CREATE TABLE contact (
  contact_id       TEXT NOT NULL,
  member_id        TEXT NOT NULL,
  campaign_id      TEXT NOT NULL,
  user_id          TEXT NOT NULL,
  started_at       TIMESTAMPTZ NOT NULL,
  ended_at         TIMESTAMPTZ,
  reached          BOOL NOT NULL,
  consent          TEXT NOT NULL,
  response         TEXT,
  notes            TEXT,
  PRIMARY KEY (contact_id),
  FOREIGN KEY (member_id) REFERENCES member (member_id),
  FOREIGN KEY (campaign_id) REFERENCES campaign (campaign_id),
  FOREIGN KEY (user_id) REFERENCES care_team_user (user_id)
);

-- Write-back events. The nightly run reads the unprocessed ones.
CREATE TABLE outcome (
  outcome_id       TEXT NOT NULL,
  contact_id       TEXT,
  member_id        TEXT NOT NULL,
  need_id          TEXT,
  action_id        TEXT,
  result           TEXT NOT NULL,
  recorded_by      TEXT NOT NULL,
  recorded_at      TIMESTAMPTZ NOT NULL,
  processed_at     TIMESTAMPTZ,
  PRIMARY KEY (outcome_id),
  FOREIGN KEY (contact_id) REFERENCES contact (contact_id),
  FOREIGN KEY (member_id) REFERENCES member (member_id),
  FOREIGN KEY (need_id) REFERENCES care_plan_need (need_id),
  FOREIGN KEY (action_id) REFERENCES action (action_id),
  FOREIGN KEY (recorded_by) REFERENCES care_team_user (user_id)
);

-- One care-plan need has at most one care-plan action
CREATE UNIQUE INDEX action_one_per_need ON action (need_id) WHERE kind = 'care_plan';
-- Nightly run picks up unprocessed outcomes
CREATE INDEX outcome_unprocessed ON outcome (recorded_at) WHERE processed_at IS NULL;

